//! Shared, schemars-typed projection types for the Zeroclaw LLM surface.
//!
//! Every struct here derives `schemars::JsonSchema` — this is mandatory per the
//! `zeroclaw-absorbs-op-llm` spec (§1). The `PluginSchema` JSON, D-Bus method
//! shapes, gRPC proto fields, MCP tool parameter schemas, and UI renderers are
//! all derived from this `schemars` output. A type without `JsonSchema` is
//! invisible to the D-Bus/gRPC/MCP surface and cannot participate in routing.
//!
//! These are the *contract* types (spec §5, Layer 1). They carry no HTTP/runtime
//! behavior — only the declared schema shape. The grpc-bridge projection hook
//! (spec §12) reads these as the single source of truth when materializing the
//! per-route / per-provider D-Bus object tree; there is no second projection.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Transport / addressing metadata for the Zeroclaw surface.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct LlmTransport {
    pub dbus_object: String,
    pub grpc_target: String,
    pub incus_container: String,
    pub browser_surface: String,
    pub rest_aliases: Vec<String>,
    /// Canonical OSCAL/subid mapping authority — referenced, never copied.
    pub policy_source: String,
}

/// A declared provider in the Zeroclaw catalog.
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
pub struct Provider {
    pub id: String,
    pub route: String,
    pub kind: String,
    #[serde(default)]
    pub aliases: Vec<String>,
    /// Optional pointer to a canonical mapping authority (e.g. the OSCAL subid
    /// registry for policy-kind providers).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,
}

/// The universal router/classifier declaration (gemma4 on-box).
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct Router {
    pub provider: String,
    pub model: String,
    pub endpoint: String,
    pub scope: String,
    pub role: String,
    pub emits: Vec<String>,
}

/// A single declared model route. Extended with selector metadata (spec §2a)
/// consumed by `selector::select_model`. New selector fields are
/// `#[serde(default)]` so existing route declarations remain valid.
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
pub struct ModelRoute {
    pub hint: String,
    pub provider: String,
    pub upstream_provider: String,
    pub transport: String,
    pub model: String,
    pub kind: String,
    pub status: String,
    pub available: bool,
    pub status_reason: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,
    /// Present (often `null`) on every route for backend key projection.
    pub api_key: Option<String>,

    // ── Selector metadata (spec §2a) ───────────────────────────────────────
    /// subid: obs.software.llm-model-route.cost-profile@v1
    #[serde(default)]
    pub cost_profile: String,
    /// subid: obs.software.llm-model-route.effort-level@v1
    #[serde(default)]
    pub effort_level: String,
    /// subid: obs.software.llm-model-route.latency-class@v1
    #[serde(default)]
    pub latency_class: String,
    /// subid: obs.software.llm-model-route.privacy-tier@v1
    #[serde(default)]
    pub privacy_tier: String,
    /// subid: obs.software.llm-model-route.context-window@v1
    #[serde(default)]
    pub context_window: u32,
    /// subid: obs.software.llm-model-route.health-score@v1
    #[serde(default)]
    pub health_score: f64,
    /// subid: obs.software.llm-model-route.fallback-routes@v1
    #[serde(default)]
    pub fallback_routes: Vec<String>,
    /// subid: obs.software.llm-model-route.tool-support@v1
    #[serde(default)]
    pub tool_support: Vec<String>,
}

/// A declared tool on the Zeroclaw surface. `parameters` is a free-form JSON
/// Schema object (kept as `serde_json::Value` because tool argument shapes are
/// dynamic and provider-defined).
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct LlmTool {
    pub name: String,
    pub description: String,
    pub parameters: serde_json::Value,
}

/// Pointer to the native (schemars) config schema for Zeroclaw.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ConfigSchema {
    pub source: String,
    pub schema_crate: String,
    pub native_type: String,
    pub status: String,
}

/// A UI surface entry rendered from a plugin schema.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct UiSurface {
    pub path: String,
    pub name: String,
    pub schema: String,
}

/// Structured-output policy for the Antigravity/Zeroclaw chat surface.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct StructuredOutput {
    pub sdk: String,
    pub config_object: String,
    pub extractor: String,
    pub response_schema: serde_json::Value,
    pub pydantic_source: Vec<String>,
    pub ui_renderer: String,
    pub required: bool,
}

/// The flattened LLM projection (spec design §2): provider catalog, route table,
/// router config, tools, structured-output policy, config schema, and UI
/// surfaces. Flattened into `ZeroclawState` so the serialized shape stays flat.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct LlmProjection {
    pub providers: Vec<Provider>,
    pub router: Router,
    pub model_routes: Vec<ModelRoute>,
    pub tools: Vec<LlmTool>,
    pub config_schema: ConfigSchema,
    pub ui_surfaces: Vec<UiSurface>,
    pub structured_output: StructuredOutput,
}

/// Weights and defaults that drive automatic model selection (spec §2c).
/// subid: sch.software.zeroclaw.selector-policy@v1
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct SelectorPolicy {
    /// subid: sch.software.selector-policy.effort-weight@v1
    pub effort_weight: f64,
    /// Coefficient applied to Zeroclaw's native cost field.
    /// subid: sch.software.selector-policy.cost-weight@v1
    pub cost_weight: f64,
    /// subid: sch.software.selector-policy.latency-weight@v1
    pub latency_weight: f64,
    /// subid: sch.software.selector-policy.health-weight@v1
    pub health_weight: f64,
    /// subid: sch.software.selector-policy.default-effort@v1
    pub default_effort: String,
    /// subid: sch.software.selector-policy.default-privacy@v1
    pub default_privacy_tier: String,
}

impl Default for SelectorPolicy {
    fn default() -> Self {
        Self {
            effort_weight: 1.0,
            cost_weight: 1.0,
            latency_weight: 0.5,
            health_weight: 0.5,
            default_effort: "medium".to_string(),
            default_privacy_tier: "internal".to_string(),
        }
    }
}

/// Input to the dynamic model selector (spec §2d).
/// subid: sch.software.llm-selection-input.schema@v1
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
pub struct SelectionInput {
    pub task_class: String,
    pub requested_effort: String,
    /// Budget class or cost ceiling policy (unit-neutral; Zeroclaw-native).
    #[serde(default)]
    pub cost_policy: Option<String>,
    #[serde(default)]
    pub latency_target: Option<String>,
    pub context_tokens: u32,
    pub privacy_tier: String,
    #[serde(default)]
    pub tool_needs: Vec<String>,
    #[serde(default)]
    pub explicit_provider: Option<String>,
    #[serde(default)]
    pub explicit_model: Option<String>,
}

/// Result of a dynamic model selection (spec §2d).
/// subid: sch.software.llm-selection-output.schema@v1
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct SelectionOutput {
    pub selected_provider: String,
    pub selected_model: String,
    pub reason: String,
    /// Cost estimate in Zeroclaw's native units (unit-neutral string).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub estimated_cost: Option<String>,
    pub effort_level: String,
    pub confidence: f64,
    pub fallback_routes: Vec<String>,
    pub event_metadata: SelectionEvent,
}

/// Audit/trace metadata emitted with every selection (spec §2d).
/// subid: evt.service.zeroclaw.selection-event@v1
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
pub struct SelectionEvent {
    pub trace_id: String,
    pub timestamp: String,
    pub selector_version: String,
}

//! Zeroclaw route surface plugin.
//!
//! Publishes the Antigravity-facing model and CLI routing contract through
//! `PluginSchema` so the UI can render provider/model controls from D-Bus.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ZeroclawState {
    pub status: String,
    pub selected_provider: String,
    pub selected_model: String,
    pub transport: Value,
    pub providers: Value,
    pub router: Value,
    pub model_routes: Value,
    pub tools: Value,
    pub config_schema: Value,
    pub ui_surfaces: Value,
    pub structured_output: Value,
}

pub struct ZeroclawPlugin;

impl Default for ZeroclawPlugin {
    fn default() -> Self {
        Self
    }
}

impl ZeroclawPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    pub(crate) fn current_state() -> ZeroclawState {
        // Decoupled from factory: local routing defaults to the on-box gemma4
        // via ollama. gemma4 is also the universal router (see `router` below).
        let selected_provider = Self::env_or("LLM_PROVIDER", "ollama");
        let selected_model = Self::env_or("LLM_MODEL", "gemma4");
        let router_endpoint = Self::env_or("ZEROCLAW_ROUTER_ENDPOINT", "http://localhost:11434");
        let wg_xray_target = Self::env_or("ZEROCLAW_WG_XRAY_TARGET", "wg-xray");
        let grpc_target = Self::env_or("ZEROCLAW_GRPC_TARGET", "http://10.200.0.1:50051");

        ZeroclawState {
            status: "declared".to_string(),
            selected_provider,
            selected_model,
            transport: json!({
                "dbus_object": "/opdbus/v1/plugins/zeroclaw",
                "grpc_target": grpc_target,
                "incus_container": wg_xray_target,
                "browser_surface": "gRPC-Web through op-web",
                "rest_aliases": ["/api/zeroclaw/chat", "/api/llm/chat"],
                // Canonical OSCAL/subid mapping authority — referenced, never copied.
                "policy_source": "/opdbus/v1/plugins/oscal_subid_registry",
            }),
            providers: json!([
                {"id": "factory", "route": "factory", "kind": "orchestrator", "aliases": ["default", "auto"]},
                {"id": "codex", "route": "openai-codex", "kind": "provider", "aliases": ["openai_codex", "codex"]},
                {"id": "ollama", "route": "ollama", "kind": "local", "aliases": ["gemma", "gemma4"]},
                {"id": "antigravity", "route": "antigravity", "kind": "orchestrator", "aliases": ["google.antigravity"]},
                {"id": "google", "route": "gemini", "kind": "provider", "aliases": ["gemini", "google-gemini"]},
                {"id": "opencode", "route": "custom:opencode", "kind": "cli", "aliases": []},
                {"id": "kilocode", "route": "custom:kilocode", "kind": "cli", "aliases": ["kilo-code", "kilo_code"]},
                {"id": "openrouter", "route": "openrouter", "kind": "router", "aliases": []},
                {"id": "anthropic", "route": "anthropic", "kind": "provider", "aliases": []},
                {"id": "openai", "route": "openai", "kind": "provider", "aliases": []},
                {"id": "gemini-cli", "route": "gemini-cli", "kind": "cli", "aliases": []},
                // OSCAL compliance routing: a policy-kind provider (assess, not chat).
                // `source` points at the canonical subid registry — the mapping
                // authority — instead of restating control mappings here.
                {"id": "oscal", "route": "oscal", "kind": "policy", "aliases": ["compliance", "subid", "nist"], "source": "/opdbus/v1/plugins/oscal_subid_registry"}
            ]),
            // gemma4 is the universal router: it classifies EVERY request into a
            // route/tag (provider+model, hint, candidate OSCAL subids). It only
            // emits tags — the deterministic layer (routes below, oscal registry,
            // xray) enforces them. Not just compliance routing.
            router: json!({
                "provider": "ollama",
                "model": "gemma4",
                "endpoint": router_endpoint,
                "scope": "all",
                "role": "context_aware_allocator",
                "emits": ["provider", "model", "hint", "candidate_subids", "confidence", "thinking_budget", "reasoning_effort"],
            }),
            model_routes: json!([
                {
                    "hint": "code",
                    "provider": "openrouter",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "gemini",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "ollama",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "gemma4 is the declared local classifier; unavailable until Ollama projects it.",
                    "api_key": null
                },
                // Factory auto-routing: selects best available provider based on query type
                {
                    "hint": "auto",
                    "provider": "factory",
                    "upstream_provider": "factory",
                    "transport": "auto",
                    "model": "auto",
                    "kind": "orchestrator",
                    "status": "declared",
                    "available": true,
                    "status_reason": "Factory auto-router available - selects best provider based on query classification.",
                    "api_key": null
                },
                {
                    "hint": "code",
                    "provider": "factory",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory code route -> openrouter/claude; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "factory",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory fast route -> gemini/flash; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "factory",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory local route -> ollama/gemma4; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "reasoning",
                    "provider": "factory",
                    "upstream_provider": "antigravity",
                    "transport": "direct",
                    "model": "gemini-3-pro-preview",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory reasoning route; Gemma dynamically allocates thinking budget.",
                    "api_key": null
                },
                // Compliance baseline routed through the OSCAL policy provider; the
                // model id is a canonical OSCAL profile reference resolved via the
                // subid registry, not an LLM model.
                {
                    "hint": "compliance",
                    "provider": "oscal",
                    "upstream_provider": "oscal",
                    "transport": "dbus",
                    "model": "NIST_SP_800-53_Rev5",
                    "kind": "policy",
                    "status": "declared",
                    "available": false,
                    "status_reason": "OSCAL policy provider is declared; unavailable until oscal_subid_registry is projected.",
                    "source": "/opdbus/v1/plugins/oscal_subid_registry",
                    "api_key": null
                }
            ]),
            tools: json!([
                {
                    "name": "zeroclaw.chat",
                    "description": "Send an Antigravity/Zeroclaw chat turn and return structured JSON when response_schema is present.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message": {"type": "string"},
                            "provider": {"type": "string"},
                            "model": {"type": "string"},
                            "response_schema": {"type": "object"}
                        },
                        "required": ["message"]
                    }
                },
                {
                    "name": "zeroclaw.models.list",
                    "description": "List cached or live models for a Zeroclaw provider.",
                    "parameters": {
                        "type": "object",
                        "properties": {"provider": {"type": "string"}},
                        "required": []
                    }
                }
            ]),
            config_schema: json!({
                "source": "zeroclaw config schema",
                "schema_crate": "schemars",
                "native_type": "zeroclaw::config::schema::Config",
                "status": "available_via_cli_or_gateway"
            }),
            ui_surfaces: json!([
                {"path": "/chat", "name": "Antigravity Chat", "schema": "zeroclaw"},
                {"path": "/grpc", "name": "gRPC Diagnostics", "schema": "plugin-service"},
                {"path": "/models", "name": "Routable Models", "schema": "zeroclaw.providers"}
            ]),
            structured_output: json!({
                "sdk": "google.antigravity",
                "config_object": "LocalAgentConfig(response_schema=UiResponseSchema)",
                "extractor": "response.structured_output()",
                "response_schema": {
                    "action": "",
                    "metadata": {},
                    "confidence_score": 0.0
                },
                "pydantic_source": [
                    "import pydantic",
                    "class UiResponseSchema(pydantic.BaseModel):",
                    "    action: str",
                    "    metadata: dict[str, str]",
                    "    confidence_score: float"
                ],
                "ui_renderer": "JsonRenderer",
                "required": true
            }),
        }
    }
}

#[async_trait]
impl StatePlugin for ZeroclawPlugin {
    fn name(&self) -> &str {
        "zeroclaw"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(super::plugin_schema_defs::zeroclaw_plugin_schema())
    }

    async fn query_current_state(&self) -> Result<Value> {
        Ok(simd_json::serde::to_owned_value(Self::current_state())?)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

