        signal_decl(
            "ModelChanged",
            "evt.service.zeroclaw.model-changed@v1",
            Some(serde_json::json!({
                "type": "object",
                "properties": {"old": {"type": "string"}, "new": {"type": "string"}, "reason": {"type": "string"}, "actor_id": {"type": "string"}}
            })),
