//! D-Bus ↔ gRPC Bidirectional Bridge
//!
//! Provides live synchronization between D-Bus objects and gRPC services:
//! - D-Bus property changes → gRPC streaming updates
//! - gRPC mutations → D-Bus method calls / property sets
//! - D-Bus signals → gRPC server-streaming
//! - All changes flow through the event chain for audit/compliance
//!
//! Architecture:
//! ```text
//!                     ┌─────────────────┐
//!                     │   Event Chain   │ ← Source of truth
//!                     │  (audit + hash) │
//!                     └────────┬────────┘
//!                              │
//!               ┌──────────────┴──────────────┐
//!               ▼                              ▼
//!     ┌─────────────────┐            ┌─────────────────┐
//!     │     D-Bus       │◄──────────►│      gRPC       │
//!     │  (local IPC)    │            │  (remote RPC)   │
//!     └─────────────────┘            └─────────────────┘
//! ```

pub mod grpc_client;
pub mod grpc_server;
pub mod interceptor;
pub mod proto_gen;
pub mod schema_engine;
pub mod schema_passthrough;
pub mod schema_router;
pub mod shared_socket;

// Re-export main types
pub use grpc_client::{GrpcClientPool, RemoteEndpoint, RemoteOperationClient};
pub use grpc_server::{run_grpc_server, OperationGrpcServer, PluginSchemaProvider};
pub use interceptor::{ghostbridge_interceptor, GhostbridgeContext};
pub use proto_gen::{ProtoGenConfig, ProtoGenerator};
pub use schema_engine::{ChangeSource, ChangeType, SchemaEngine, StateChange};
pub use schema_passthrough::{ResolvedRoute, SchemaPassthroughService};
pub use schema_router::{PluginRoute, SchemaRouter, SchemaRouterError};
pub use shared_socket::{bind_shared_socket, uds_identity_interceptor, CanonicalPeerIdentity};

/// Generated protobuf types — one sub-module per domain proto.
/// All are compiled into the combined operation_descriptor.bin for reflection.
pub mod proto {
    // Core: StateSync, PluginService, EventChainService, OvsdbMirror, RuntimeMirror
    tonic::include_proto!("operation.v1");

    pub mod mail {
        tonic::include_proto!("operation.mail.v1");
    }
    pub mod privacy {
        tonic::include_proto!("operation.privacy.v1");
    }
    pub mod registration {
        tonic::include_proto!("operation.registration.v1");
    }
    pub mod registry {
        tonic::include_proto!("operation.registry.v1");
    }

    /// Combined FileDescriptorSet covering all domain protos.
    /// Served by tonic-reflection so clients can discover every service.
    pub const FILE_DESCRIPTOR_SET: &[u8] =
        tonic::include_file_descriptor_set!("operation_descriptor");
}

        router.engine = Some(engine);
        router
    }

    /// Create a SchemaRouter with explicit SHM paths.
    ///
    /// In production, use [`new`](Self::new) which targets the canonical
    /// `/dev/shm` layout. Tests supply temporary paths to exercise the
    /// manifest-hash change-detection path without touching live SHM.
    pub fn with_paths(
        dbus_connection: Arc<tokio::sync::OnceCell<Connection>>,
        monolith_path: PathBuf,
        per_plugin_dir: PathBuf,
        manifest_path: PathBuf,
    ) -> Self {
        let routes = Self::load_routes_from(&monolith_path, &per_plugin_dir);
        let cached_hash = Self::read_manifest_hash_at(&manifest_path);
        info!(
            count = routes.len(),
            "SchemaRouter initialized from schema catalog"
        );
        Self {
            routes: Arc::new(RwLock::new(routes)),
            dbus_connection,
            monolith_path,
            per_plugin_dir,
            manifest_path,
            cached_hash: Arc::new(RwLock::new(cached_hash)),
            engine: None,
        }
    }

    /// Register D-Bus objects for all plugins in the catalog.
    ///
    /// This makes the bridge the authoritative creator of the D-Bus objects
    /// defined in the schema.
    pub async fn register_objects(&self) -> anyhow::Result<()> {
        let conn = self
            .dbus_connection
            .get()
            .ok_or_else(|| anyhow::anyhow!("D-Bus connection not initialized"))?;

        let routes = self.routes.read().await;
        for (plugin_id, route) in routes.iter() {
            let interface = SchemaBackedInterface::with_engine(
                plugin_id.clone(),
                route.clone(),
                self.engine.clone(),
            );
            let path = route.dbus_path.clone();

            debug!(plugin_id, path, "Registering authoritative D-Bus object");
            if let Err(e) = conn.object_server().at(path.as_str(), interface).await {
                debug!(plugin_id, path, error = %e, "Failed to register D-Bus object (likely already registered)");
            }
        }
        Ok(())
    }

    /// Reload routes and re-register objects.
    pub async fn reload(&self) -> anyhow::Result<()> {
        let count = self.reload_routes_only().await;
        info!(count, "SchemaRouter reloaded plugin routes");
        self.register_objects().await
    }

    /// Reload routes from the SHM catalog into the in-memory route table
    /// without touching the D-Bus object server. Returns the route count.
    ///
    /// This is a direct read of the schema files — no polling, no watchers.
    async fn reload_routes_only(&self) -> usize {
        let routes = Self::load_routes_from(&self.monolith_path, &self.per_plugin_dir);
